  Lemma argH0_low : forall z, 0 <= z < sp0z + 24 ->
    AsanInitP.argHp sp0 rdraw inp E (Z_to_bv 64 z) = false.
  Proof using sp0 brk0 rdraw inp E Vsp Vav.   (* the argument list its consumers apply *)
    (* LPS 727298f3: [argB0] (AsanInit.v) is [usp + 24, usp + 8 argc + 8 envc + 24) or [STR0, utop)
       with STR0 = usp + C + W and C = block_head_size >= 24: both start at or above usp + 24
       (the text of boost-beast/http_request's As/AsMainCells.v) *)
    intros z Hz. pose proof Vsp as Vsp'. destruct Vsp' as [Vlo [Vhi _]]. unfold sp_window_lo, sp_window_hi in Vlo, Vhi. unfold sp0z in Hz.
    assert (HC0 : (24 <= block_head_size (kb_rseq (in_kernel inp)) (in_argv inp) (in_envp inp))%nat)
      by (unfold block_head_size, block_items; cbv zeta; lia).
    unfold AsanInitP.argHp, AsanInit.argH0. apply andb_false_iff. left. unfold AsanInit.argB0. cbv zeta. rewrite u_of_Z by lia.
    apply orb_false_iff. split; apply andb_false_iff; left; apply Z.leb_gt; lia.
  Qed.

  Lemma hid_img : forall z, 65536 <= z < 7430144 -> HID (Z_to_bv 64 z) = false.
  Proof.
    (* LPS 727298f3: text (boost-beast/http_request's As/AsMainCells.v, this image's hull) *)
    intros z Hz. pose proof Vsp as Vsp'. destruct Vsp' as [Vlo _]. unfold sp_window_lo in Vlo.
    unfold hid. apply orb_false_iff. split; [apply argH0_low; unfold sp0z; lia|].
    apply negb_false_iff. unfold vis. rewrite u_of_Z by lia. replace (in_hull ASAN_H z) with true; [reflexivity|].
    symmetry. unfold in_hull. change (img_lo ASAN_H) with 65536. change (img_hi ASAN_H) with 7430144.
    apply andb_true_intro. split; [apply Z.leb_le | apply Z.ltb_lt]; lia.
  Qed.

