    rewrite (in_ivs_zz sp0 brk0 _ _ (zz_ok_noacc sp0 brk0 rdraw inp h ch E R FULL model Vsp Vbrk Vav Vev Hh HC)).
    replace (zin z (PM_MAPS (bv_unsigned brk0) (Xof g E))) with true by (symmetry; apply zin_iff; exact HM).
