  (* [comment removed for export] *)
  Definition visibleZ (sp0z brk0z argc : Z) (X : pm_syms) (z : Z) : Prop :=
    (65536 <= z < 7430144)
    \/ (zinP z (VISK sp0z brk0z X) /\ ~ zinP z (PM_NOACC brk0z X))
    (* LPS 727298f3: below argv[2]'s slot, where [argB0]'s pointer arm starts; [argc] stays a
       parameter so every consumer's argument list is unchanged *)
    \/ (sp0z - 0x800000 <= z < sp0z + 24)
    \/ ((exists a n, In (a, n) (VISZ0 sp0z brk0z X) /\ 0x7fff8000 + a / 8 <= z < 0x7fff8000 + (a + n) / 8)
        /\ zinP z (PM_MAPS brk0z X) /\ ~ zinP z (PM_NOACC brk0z X)).   (* [comment removed for export] *)
  Lemma visibleZ_hid : forall z, visibleZ sp0z brk0z (Z.of_nat (length (in_argv inp))) X z -> HID (Z_to_bv 64 z) = false.
Proof.
  intros z [Hz|[(H1 & H2)|[Hz|((a & n & HIN & Hsh) & HM & HN)]]];
    [apply hid_img; exact Hz | apply hid_vis; assumption | apply hid_stack; exact Hz | eapply hid_sh; eassumption].
Qed.

  (* [comment removed for export] *)
  (* LPS 727298f3: [wrap_mem] takes the run and its mmap base, which [SINVm] binds
     existentially, so the argument bytes are stated at SOME launch base (the shape of
     boost-beast/http_request's As/AsMainCells.v) *)
  Lemma args_block : exists mb, AsanInitP.launch_base_ok sp0 rdraw brk0 inp mb /\
    forall a, AsanInitP.argBp sp0 rdraw inp a = true ->
      FULL a = wrap_mem inp mb APH (Z_to_bv 64 (Z.of_N A_PC)) sp0 rdraw a.
  Proof using sp0 brk0 rdraw inp ch E R FULL model Vsp Vav Vev Vfit HC.   (* the argument list its consumers apply *)
    destruct (AsanInitP.SINVm_mem _ _ _ _ _ _ _ _ (co_sinv _ _ _ _ _ _ _ _ _ _ _ HC)) as (mb & Hb & HM).
    exists mb. split; [exact Hb|]. intros a Ha. apply HM.
    pose proof (AsanInitP.SINVm_sp0 _ _ _ _ _ _ Vsp Vav Vev _ _ (co_sinv _ _ _ _ _ _ _ _ _ _ _ HC)) as S0.
    (* every hidden-argument address is at or above sp0 ([argB0]'s two arms) *)
    assert (Hge : bv_unsigned sp0 <= bv_unsigned a).
    { unfold AsanInitP.argBp, AsanInit.argB0 in Ha. cbv zeta in Ha.
      apply orb_true_iff in Ha as [Ha|Ha]; apply andb_true_iff in Ha as [Ha _]; apply Z.leb_le in Ha; lia. }
    unfold AsanInitP.argBp in Ha. unfold AsanInitP.argHp, AsanInit.argH0. rewrite Ha. cbn [andb].
    apply Z.leb_le. eapply Z.le_trans; [apply Z.eq_le_incl; exact S0 | exact Hge].
  Qed.
End CELLS.

